({
  init(msg) {
    this._ensureState();
    this._checkInvariants();
    return true;
  },

  addItem(msg) {
    const { sku, price, qty = 1, taxable = true } = msg.payload || {};

    // Preconditions
    this.ensure(typeof sku === 'string' && sku.trim().length > 0, 'SKU must be a non-empty string');
    this.ensure(typeof price === 'number' && !Number.isNaN(price) && price >= 0, 'Price must be a non-negative number');
    this.ensure(typeof qty === 'number' && !Number.isNaN(qty) && qty > 0, 'Quantity must be a positive number');
    this.ensure(typeof taxable === 'boolean', 'Taxable flag must be a boolean');

    this._ensureState();

    const normalizedSku = sku.trim();
    const existingIndex = this.data.items.findIndex(item => item.sku === normalizedSku);

    if (existingIndex >= 0) {
      this.data.items[existingIndex].qty += qty;
      this.data.items[existingIndex].price = price;
      this.data.items[existingIndex].taxable = taxable;
    } else {
      this.data.items.push({
        sku: normalizedSku,
        price,
        qty,
        taxable
      });
    }

    this._checkInvariants();
    this.changed('items', this.data.items);

    const savedItem = this.data.items.find(item => item.sku === normalizedSku);
    // Postcondition
    this.ensure(savedItem !== undefined && savedItem.qty >= qty, 'Item must be stored in the cart');

    return savedItem;
  },

  applyDiscount(msg) {
    const { code, percent } = msg.payload || {};

    // Preconditions
    this.ensure(typeof code === 'string' && code.trim().length > 0, 'Discount code must be a non-empty string');
    this.ensure(
      typeof percent === 'number' && !Number.isNaN(percent) && percent >= 0 && percent <= 100,
      'Discount percent must be a number between 0 and 100'
    );

    this._ensureState();

    const normalizedCode = code.trim();
    this.data.discount = {
      code: normalizedCode,
      percent
    };

    this._checkInvariants();
    this.changed('discount', this.data.discount);

    // Postcondition
    this.ensure(
      this.data.discount && this.data.discount.code === normalizedCode && this.data.discount.percent === percent,
      'Discount must be successfully applied to the cart'
    );

    return this.data.discount;
  },

  calculateTotal(msg) {
    const { taxRate = 0, shippingCost = 0 } = msg.payload || {};

    // Preconditions
    this.ensure(typeof taxRate === 'number' && !Number.isNaN(taxRate) && taxRate >= 0, 'taxRate must be a non-negative number');
    this.ensure(typeof shippingCost === 'number' && !Number.isNaN(shippingCost) && shippingCost >= 0, 'shippingCost must be a non-negative number');

    this._ensureState();

    const subtotal = this.data.items.reduce((sum, item) => sum + (item.price * item.qty), 0);
    const discountPercent = this.data.discount ? this.data.discount.percent : 0;
    const discountAmount = subtotal * (discountPercent / 100);
    const discountedSubtotal = Math.max(0, subtotal - discountAmount);

    const discountMultiplier = subtotal > 0 ? (1 - discountPercent / 100) : 1;
    const taxableSubtotal = this.data.items
      .filter(item => item.taxable)
      .reduce((sum, item) => sum + (item.price * item.qty), 0);

    const discountedTaxableSubtotal = taxableSubtotal * discountMultiplier;
    const tax = discountedTaxableSubtotal * taxRate;
    const total = discountedSubtotal + tax + shippingCost;

    const summary = {
      itemCount: this.data.items.reduce((count, item) => count + item.qty, 0),
      subtotal,
      discountCode: this.data.discount ? this.data.discount.code : null,
      discountPercent,
      discountAmount,
      discountedSubtotal,
      taxableSubtotal,
      taxRate,
      tax,
      shippingCost,
      total: Math.round(total * 100) / 100
    };

    // Postcondition
    this.ensure(typeof summary.total === 'number' && summary.total >= 0, 'Total calculation must yield a non-negative number');

    return summary;
  },

  getItems(msg) {
    this._ensureState();
    return this.data.items.slice();
  },

  _ensureState() {
    if (!this.data || typeof this.data !== 'object') {
      this.data = {};
    }
    if (!Array.isArray(this.data.items)) {
      this.data.items = [];
    }
    if (this.data.discount === undefined) {
      this.data.discount = null;
    }
  },

  _checkInvariants() {
    this.invariant(this.data && typeof this.data === 'object', 'this.data must be an object');
    this.invariant(Array.isArray(this.data.items), 'this.data.items must be an array');

    for (let i = 0; i < this.data.items.length; i++) {
      const item = this.data.items[i];
      this.invariant(typeof item.sku === 'string' && item.sku.length > 0, 'Every cart item must have a valid SKU');
      this.invariant(typeof item.price === 'number' && item.price >= 0, 'Every cart item price must be non-negative');
      this.invariant(typeof item.qty === 'number' && item.qty > 0, 'Every cart item quantity must be positive');
      this.invariant(typeof item.taxable === 'boolean', 'Every cart item taxable property must be a boolean');
    }

    if (this.data.discount !== null) {
      this.invariant(typeof this.data.discount === 'object', 'Discount state must be an object if present');
      this.invariant(
        typeof this.data.discount.code === 'string' && this.data.discount.code.length > 0,
        'Discount code must be a non-empty string'
      );
      this.invariant(
        typeof this.data.discount.percent === 'number' &&
        this.data.discount.percent >= 0 &&
        this.data.discount.percent <= 100,
        'Discount percent must be within [0, 100]'
      );
    }
  }
})
